import{_ as a,o as e,c as i,a2 as t}from"./chunks/framework.CiKk3sJz.js";const u=JSON.parse('{"title":"漫画 · 第 31 话 锚点定位：把元素钉在另一个元素旁边","description":"","frontmatter":{},"headers":[],"relativePath":"comics/css/EP.31-anchor-positioning.md","filePath":"comics/css/EP.31-anchor-positioning.md","lastUpdated":1792579602000}'),r={name:"comics/css/EP.31-anchor-positioning.md"};function n(c,o,s,l,d,h){return e(),i("div",null,[...o[0]||(o[0]=[t('<h1 id="漫画-·-第-31-话-锚点定位-把元素钉在另一个元素旁边" tabindex="-1">漫画 · 第 31 话 锚点定位：把元素钉在另一个元素旁边 <a class="header-anchor" href="#漫画-·-第-31-话-锚点定位-把元素钉在另一个元素旁边" aria-label="Permalink to &quot;漫画 · 第 31 话 锚点定位：把元素钉在另一个元素旁边&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/css/21-anchor-positioning">docs/css/21-anchor-positioning.md</a> ｜ 原画：<a href="./EP.31-anchor-positioning.svg">EP.31-anchor-positioning.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。每个 Tooltip 都要写 <code>getBoundingClientRect()</code> + scroll 监听 + rAF 节流，定位 JS 比样式还多。</li><li><strong>标签君</strong>：HTML5 结构师，搬出 <code>anchor-name</code> 与 <code>position-anchor</code>，一句声明建立几何绑定，布局引擎接管跟随。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>像素酱被「让 Tooltip 永远贴在按钮上方」折磨：监听 scroll/resize、手动节流、快速滚动还抖动。标签君引入锚点定位——锚元素声明 <code>anchor-name: --tip</code>，漂浮物声明 <code>position-anchor: --tip</code> + <code>bottom: anchor(top)</code>，跟随变成浏览器的布局职责。像素酱发现 <code>position-try: flip-block</code> 连「空间不足自动翻转」都内建了。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>传统方案命令式重算：<code>getBoundingClientRect()</code> + 滚动监听 + rAF 节流。定位 JS 占组件库三分之一体积，SSR 输出结构不完整，快速滚动时跳帧抖动。叠加痛苦还有翻转、等宽、overflow 裁切，每个都需要 Popper.js 中间件。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>锚点定位是<strong>布局期</strong>声明：<code>anchor-name</code> 建立名字，<code>position-anchor</code> 完成绑定，<code>anchor()</code> 函数或 <code>position-area</code> 九宫格决定位置。高级工具箱：<code>position-try</code> 防溢出翻转、<code>anchor-size()</code> 读锚尺寸。滚动跟随由布局引擎逐帧保证，零 JS、零抖动。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>四大场景：Tooltip 正上方居中、下拉菜单等宽、防溢出自动翻转、角标骑角落。记住分界：锚点定位<strong>只管几何、不管层叠</strong>——被 overflow 裁切或需要 z-index 霸权时，请搭配下一话的 Popover top layer。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>锚点定位发生在布局阶段：锚移动 → 漂浮物下一帧自动重算，零 JS 参与。</li><li>position-try 翻转无动画：这是布局期一次性决策，不要期待过渡。</li><li>只管几何、不管层叠：被 overflow 裁切请搭配 Popover top layer。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：<code>position: fixed</code> 的漂浮物能用锚点定位跟随页面滚动吗？为什么？</p><p><strong>答</strong>：不能。<code>fixed</code> 相对视口定位，锚移动后不会自动重算。要跟随滚动请用 <code>position: absolute</code> 并确保漂浮物与锚在同一滚动上下文中。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>基础 Tooltip + position-area 九宫格切换 + 防溢出翻转 + anchor-size 等宽菜单 + 滚动跟随：<a href="./../../examples/css/21-anchor-positioning/index-01-anchor-positioning.html">examples/css/21-anchor-positioning/</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 32 话《Popover API》——<code>popover</code> 属性与 <code>popovertarget</code>，浏览器原生顶层弹出层：top layer 层叠、light dismiss、Esc 关闭、焦点管理，全部零 JS。</p>',22)])])}const g=a(r,[["render",n]]);export{u as __pageData,g as default};
